INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-20-austria-why-early-adopter', '2026-01-20', '2026-01', 'Austria mandated B2G e-invoicing in 2014 — years before most EU peers — and, unusually, accepts two entirely distinct formats rather than one national standard.', '<h3>🇦🇹 Why Austria''s e-invoicing story starts a decade earlier than most</h3>
<p>Most countries on this tracker arrived at structured e-invoicing through a 2020s mandate. Austria got there first: since 1 January 2014, the Republic of Austria has refused paper invoices from suppliers to federal government bodies (IKTKonG §5, BGBl. I Nr. 35/2012) — one of the earliest B2G mandates anywhere in the EU, years ahead of Germany''s own B2G requirement and predating most of the countries already on this tracker.</p>
<p>What makes Austria''s case genuinely unusual isn''t just the early date — it''s that the country accepts two entirely distinct formats for the same obligation. ebInterface, a national XML standard developed since 2009 by AUSTRIAPRO (a working group of the WKO, Austria''s Federal Economic Chamber), sits alongside Peppol BIS 3.0 as an equally valid choice. Both have been EN 16931-aligned since ebInterface 5.0, so a business capable of either format is fully compliant — a flexibility most peers on this tracker, which typically mandate a single national format, don''t offer.</p>
<p>The 2018 Federal Public Procurement Act (BVergG 2018, §368) extended the obligation beyond core federal ministries to all central contracting authorities, and several of Austria''s nine Länder — including Vienna, Lower Austria, and Upper Austria — have since adopted comparable requirements of their own. B2B, meanwhile, has remained entirely voluntary throughout this entire decade-plus history — though that''s now under active review, as the next story in this archive covers.</p>', 'https://www.erechnung.gv.at', 1);
